-- RFC 030 WP3: revenue leak scan runs (bounded historical sweeps with
-- deterministic detectors). Counts, errors, and source freshness make
-- reruns incremental and auditable.
CREATE TABLE IF NOT EXISTS `revenue_leak_scans` (`id` uuid NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `status` text NOT NULL DEFAULT ('pending'), `mode` text NOT NULL DEFAULT ('local'), `lookback_days` integer NOT NULL DEFAULT (90), `threads_seen` integer NOT NULL DEFAULT (0), `candidates_seen` integer NOT NULL DEFAULT (0), `relationships_created` integer NOT NULL DEFAULT (0), `evidences_created` integer NOT NULL DEFAULT (0), `actions_created` integer NOT NULL DEFAULT (0), `started_at` datetime NULL, `completed_at` datetime NULL, `error` text NULL, `source_freshness_at` datetime NULL, `revenue_workspace_id` uuid NOT NULL, `user_revenue_leak_scans` uuid NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `revenue_leak_scans_revenue_workspaces_scans` FOREIGN KEY (`revenue_workspace_id`) REFERENCES `revenue_workspaces` (`id`) ON DELETE NO ACTION, CONSTRAINT `revenue_leak_scans_users_revenue_leak_scans` FOREIGN KEY (`user_revenue_leak_scans`) REFERENCES `users` (`id`) ON DELETE NO ACTION);
CREATE INDEX IF NOT EXISTS `revenueleakscan_status_revenue_workspace_id` ON `revenue_leak_scans` (`status`, `revenue_workspace_id`);
